# ---------------------------------------------------------------------------
# Everything below builds the packets with struct. LEAF holds, per TLV tag,
# bodies that were found with scan.py (a search over lengths and sparse
# random contents against the dissector) to decode with the exact TLV length.
# ---------------------------------------------------------------------------
import struct
import sys
import os

LEAF = {int(k): v for k, v in json.loads(LEAFJSON).items()}
# HARQ TDD TLV bodies per (tag, mode, count), also found by search
HARQ = {tuple(int(x) for x in k.split(',')): bytes.fromhex(v) for k, v in json.loads(HARQJSON).items()}


def exp(name=b"nfapi"):
    n = name + b"\0" * ((4 - len(name) % 4) % 4)
    return struct.pack(">HH", 12, len(n)) + n + struct.pack(">HH", 0, 0)


def tlv(tag, body):
    return struct.pack(">HH", tag, len(body)) + body


def leaf(tag, k=0):
    b = LEAF[tag]
    return tlv(tag, bytes.fromhex(b[k % len(b)]))


def leaves(tag):
    return b"".join(tlv(tag, bytes.fromhex(b)) for b in LEAF[tag])


def p45(msgid, payload, phy=0, spare=0):
    return struct.pack(">HHHH", phy, msgid, 8 + len(payload), spare) + payload


def p7(msgid, payload, m=0, seg=0, seq=0, phy=0, cks=0, ts=0, length=None):
    ln = 16 + len(payload) if length is None else length
    return struct.pack(">HHHBBII", phy, msgid, ln, (m << 7) | seg, seq, cks, ts) + payload


def inst(tlvs):
    return struct.pack(">H", 2 + len(tlvs)) + tlvs


def pdu(ptype, tlvs):
    return struct.pack(">BB", ptype, 2 + len(tlvs)) + tlvs


SFN = struct.pack(">H", 0x1234)

DL_GROUPS = {
    0: [(0x2001,), (0x2001, 0x2002), (0x2001, 0x2003), (0x2039,), (0x203A,), (0x203B,)],
    1: [(0x2004,)],
    2: [(0x2005,)],
    3: [(0x2006,), (0x2006, 0x2007), (0x2006, 0x2007, 0x2008), (0x203C,), (0x203D,), (0x203E,)],
    4: [(0x2009,), (0x203F,)],
    5: [(0x200A,)],
    6: [(0x200B,), (0x2040,)],
    7: [(0x2041,), (0x2042,)],
    8: [(0x205B,)],
}
UL_GROUPS = {
    0: [(0x200D, 0x200F), (0x200E, 0x200F), (0x2043,), (0x2044,)],
    1: [(0x200D, 0x2010), (0x2011,), (0x2045,)],
    2: [(0x200D, 0x2012), (0x2046,)],
    3: [(0x200D, 0x2010, 0x2012)],
    4: [(0x2013, 0x2014), (0x2015,), (0x2049,)],
    5: [(0x2013, 0x2016), (0x2017,)],
    6: [(0x2013, 0x2018), (0x2019,), (0x201A,), (0x204A,), (0x204B,)],
    7: [(0x2013, 0x2016, 0x2019)],
    8: [(0x2013, 0x2014, 0x2019)],
    9: [(0x2013, 0x2014, 0x2016)],
    10: [(0x2013, 0x2014, 0x2016, 0x2019)],
    11: [(0x201B,), (0x201C,), (0x204C,)],
    12: [(0x2047,), (0x2048,)],
    13: [(0x200D, 0x2045), (0x2047,)],
    14: [(0x200D, 0x204A)],
    15: [(0x200D, 0x204B, 0x2049)],
}
HI_GROUPS = {
    0: [(0x201E,), (0x201F,)],
    1: [(0x2020,), (0x2021,), (0x204D,)],
    2: [(0x2020, 0x204D)],
    3: [(0x204E,)],
}


def group(g, k):
    return b"".join(leaf(t, k + i) for i, t in enumerate(g))


def dl_body(k, nd, npd, sym=2, rnti=3, pwr=6000):
    pdus = b""
    for i in range(nd + npd):
        ptype = (k + i) % 9
        gs = DL_GROUPS[ptype]
        pdus += pdu(ptype, group(gs[(k + i) % len(gs)], k + i))
    return struct.pack(">BBHBH", sym, nd, npd, rnti, pwr) + pdus


def ul_body(k, n, rach=1, srs=0):
    pdus = b""
    for i in range(n):
        ptype = (k + i) % 16
        gs = UL_GROUPS[ptype]
        pdus += pdu(ptype, group(gs[(k + i) % len(gs)], k + i))
    return struct.pack(">BBB", n, rach, srs) + pdus


def hi_body(k, nd, nh):
    pdus = b""
    for i in range(nd + nh):
        if i >= nd:
            ptype = 0
        else:
            ptype = 1 + (k + i) % 3
        gs = HI_GROUPS[ptype]
        pdus += pdu(ptype, group(gs[(k + i) % len(gs)], k + i))
    return struct.pack(">HBB", 0x4321, nd, nh) + pdus


def tx_body(pls):
    out = struct.pack(">H", len(pls))
    for i, p in enumerate(pls):
        out += struct.pack(">HH", len(p), i) + p
    return out


def list_body(n, mk, cnt_fmt=">H"):
    return struct.pack(cnt_fmt, n) + b"".join(inst(mk(i)) for i in range(n))


def rx_body(k, n):
    # TLVs 0x2038 (UE info), 0x2024 (RX PDU rel8: length, data offset, UL CQI,
    # timing advance), optional 0x2025; the PDU data follows at the data offset
    def tlvs(off):
        res = b""
        for i in range(n):
            res += leaf(0x2038, k + i)
            res += tlv(0x2024, struct.pack(">HHBH", 3 + i, off, 9, 7))
            if i % 2 == 0:
                res += leaf(0x2025, k + i)
        return res
    off = 2 + len(tlvs(0))
    data = b"".join(bytes(range(3 + i)) for i in range(n))
    return struct.pack(">H", n) + tlvs(off) + data


def cqi_body(k, lengths):
    # The dissector's pre-scan reads two octets past each instance, so only a
    # single instance followed by the CQI data is clean
    out = struct.pack(">H", len(lengths))
    data = b""
    for i, ln in enumerate(lengths):
        t = leaf(0x2038, k + i)
        if (k + i) % 2 == 0:
            c = tlv(0x202F, struct.pack(">HBBBBBB", ln, 1, 2, 3, 4, 5, 6))
        else:
            c = tlv(0x2030, struct.pack(">H", ln) + bytes.fromhex(LEAF[0x2030][(k + i) % len(LEAF[0x2030])])[2:])
        out += inst(t + c + leaf(0x2052, k + i))
        data += bytes(range(ln))
    return out + data


def frames_p5():
    fr = []
    for m in (0x0104, 0x0106, 0x0108, 0x010C, 0x010E, 0x020F):
        fr.append(p45(m, b""))
    fr.append(p45(0x0104, b"", phy=3, spare=0x55aa))
    for m in (0x0100, 0x0102, 0x0110):
        for t in (0x1000, 0x1001, 0x1003, 0x1005):
            fr.append(p45(m, leaf(t)))
    for m in (0x0103, 0x0105, 0x0107, 0x010B, 0x010D, 0x010F):
        for e in (0, 1, 2, 3, 4, 5, 6, 7, 8, 99):
            fr.append(p45(m, struct.pack(">I", e)))
    for m in (0x0201, 0x0204, 0x0207, 0x020A, 0x020D, 0x0210):
        for e in (100, 101, 102, 103, 200, 201, 202, 300, 301, 302, 303, 7):
            fr.append(p45(m, struct.pack(">I", e)))
    for m in (0x0101, 0x0111):
        fr.append(p45(m, struct.pack(">I", 0) + leaf(0x1000) + leaf(0x1001) + leaf(0x1002) + leaf(0x1003)))
        fr.append(p45(m, struct.pack(">I", 2)))
    for m in (0x0202, 0x0205, 0x0208, 0x020B, 0x020E):
        for e in (100, 300, 302):
            fr.append(p45(m, struct.pack(">I", e) + leaf(0x3003) + leaf(0x3007)))
    for m in (0x0200, 0x0203, 0x0206, 0x0209, 0x020C):
        for r in (0, 1, 2, 3):
            fr.append(p45(m, struct.pack(">B", r) + leaf(0x3000) + leaf(0x3004, 1)))
    cfg = [t for t in sorted(LEAF) if t < 0x15]
    fr.append(p45(0x0109, struct.pack(">BB", 0, 3) + leaf(0x0001) + leaf(0x0002) + leaf(0x0003)))
    fr.append(p45(0x0109, struct.pack(">BB", 1, 0)))
    fr.append(p45(0x010A, struct.pack(">B", len(cfg)) + b"".join(leaf(t) for t in cfg)))
    fr.append(p45(0x010A, struct.pack(">B", 0)))
    fr.append(p45(0x0300, b"\x01\x02\x03\x04"))
    fr.append(p45(0x03FF, b""))
    fr.append(p45(0x0999, b"\xde\xad\xbe\xef"))
    fr.append(p45(0x0082, b"\xaa\xbb"))
    return fr


def frames_tags():
    """One frame per TLV tag holding all its bodies, in the list kinds of
    P4/P5 messages, plus unknown tags."""
    fr = []
    msgs = (0x0100, 0x0102, 0x0110)
    for n, t in enumerate(sorted(LEAF)):
        if t < 0x1000:
            fr.append(p45(0x010A, struct.pack(">B", len(LEAF[t])) + leaves(t)))
        else:
            fr.append(p45(msgs[n % 3], leaves(t)))
    # gaps in the configuration table (NULL names), tags the table maps to
    # other entries, unknown tags and vendor extensions
    for t in (0x0000, 0x0006, 0x0007, 0x0008, 0x0009, 0x000F, 0x0010, 0x0011, 0x0012, 0x0013, 0x0017,
              0x001D, 0x0021, 0x009E, 0x0106, 0x0109, 0x0134, 0x0200, 0x1010, 0x205C, 0x301B, 0x4000, 0xF000,
              0xF123, 0xFFFF):
        fr.append(p45(0x0100, tlv(t, b"\x01\x02\x03")))
    # zero length TLVs, known and unknown
    fr.append(p45(0x0100, tlv(0x1000, b"") + tlv(0x2000, b"") + tlv(0x7000, b"")))
    return fr


def frames_p7():
    fr = []
    fr.append(p7(0x0180, struct.pack(">III", 1, 2, 3), seq=1, ts=100))
    fr.append(p7(0x0181, struct.pack(">II", 4, 5), seq=2, ts=200))
    fr.append(p7(0x0182, struct.pack(">" + "I" * 14, *range(1, 15)), seq=3, ts=300))
    h = [0x2027, 0x2028, 0x2029, 0x202A, 0x204F, 0x2050]
    for k in range(4):
        body = tlv(0x2026, list_body(len(h), lambda i: leaf(h[i], k + i)))
        fr.append(p7(0x0085, SFN + body, seq=k))
    fr.append(p7(0x0085, SFN + tlv(0x2026, struct.pack(">H", 0)), seq=9))
    for k in range(3):
        body = tlv(0x202B, list_body(3, lambda i: leaf(0x202C, k + i)))
        fr.append(p7(0x0086, SFN + body, seq=k))
    for k in range(3):
        fr.append(p7(0x0087, SFN + tlv(0x2023, rx_body(k, 1 + k)), seq=k))
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 0)), seq=7))
    rt = [0x2032, 0x2033, 0x2051]
    for k in range(3):
        body = tlv(0x2031, list_body(3, lambda i: leaf(rt[(i + k) % 3], k + i)))
        fr.append(p7(0x0088, SFN + body, seq=k))
    st = [(0x2035,), (0x2035, 0x2036), (0x2037,), (0x2053,), (0x2054,), (0x2035, 0x2038)]
    for k in range(3):
        body = tlv(0x2034, list_body(len(st), lambda i: b"".join(leaf(x, k + i) for x in st[i]), ">B"))
        fr.append(p7(0x0089, SFN + body, seq=k))
    for k in range(3):
        body = tlv(0x202D, list_body(2, lambda i: leaf(0x2038, k + i) + leaf(0x2052, k + i)))
        fr.append(p7(0x008A, SFN + body, seq=k))
    for k in range(3):
        fr.append(p7(0x008B, SFN + tlv(0x202E, cqi_body(k, [4 + k])), seq=k))
        fr.append(p7(0x008B, SFN + tlv(0x202E, cqi_body(k, [5])), seq=k + 4))
    for k, (nd, npd) in enumerate([(1, 1), (2, 3), (0, 6), (3, 0), (1, 9)]):
        fr.append(p7(0x0080, SFN + tlv(0x2000, dl_body(k, nd, npd)), seq=k))
    fr.append(p7(0x0080, SFN + tlv(0x2000, dl_body(0, 0, 0, sym=7, pwr=20000)), seq=9))
    for k, n in enumerate([1, 2, 5, 16, 16]):
        fr.append(p7(0x0081, SFN + tlv(0x200C, ul_body(k * 3, n, rach=k % 3, srs=k % 2)), seq=k))
    for k, (nd, nh) in enumerate([(1, 1), (3, 2), (2, 0), (0, 3)]):
        fr.append(p7(0x0083, SFN + tlv(0x201D, hi_body(k, nd, nh)), seq=k))
    fr.append(p7(0x0084, SFN + tlv(0x2022, tx_body([b"\x01\x02\x03", b"", b"abcdefgh"])), seq=1))
    fr.append(p7(0x0084, SFN + tlv(0x2022, tx_body([])), seq=2))
    for k, n in enumerate([1, 2, 0, 3]):
        body = struct.pack(">H", n) + b"".join(
            pdu(i % 2, leaf([0x2056, 0x2057][i % 2], k + i)) for i in range(n))
        fr.append(p7(0x008C, SFN + tlv(0x2055, body), seq=k))
        body = struct.pack(">H", n) + b"".join(
            pdu(i % 2 if k != 3 else 5, leaf([0x2059, 0x205A][i % 2], k + i)) for i in range(n))
        fr.append(p7(0x008D, SFN + tlv(0x2058, body), seq=k))
    fr.append(p7(0x0085, SFN))
    fr.append(p7(0x0081, SFN + tlv(0x7777, b"abc") + tlv(0xF001, b"")))
    return fr


def pnf_phy_instance(idx, rfs, excl, dlbw, ulbw, dl_layers, ul_layers, rel, nmm):
    return (struct.pack(">HH", idx, len(rfs)) + b"".join(struct.pack(">H", x) for x in rfs) +
            struct.pack(">H", len(excl)) + b"".join(struct.pack(">H", x) for x in excl) +
            struct.pack(">HHBBHB", dlbw, ulbw, dl_layers, ul_layers, rel, nmm))


def frames_pnf_phy():
    fr = []
    # PNF PHY (0x1001) with PHY instances: RF and exclusion lists, bandwidth bitmasks,
    # layer counts (valid and invalid), maximum release and NMM modes
    insts = [
        pnf_phy_instance(1, [1, 2], [3], 0x3F, 0x15, 1, 2, 0x3F, 3),
        pnf_phy_instance(2, [], [], 0x01, 0x20, 4, 8, 0x01, 0),
        pnf_phy_instance(3, [7], [8, 9, 10], 0x0F, 0x0F, 3, 5, 0x0F, 1),
        pnf_phy_instance(4, [], [], 0x7F, 0xFF, 9, 0, 0x7F, 9),
    ]
    fr.append(p45(0x0101, struct.pack(">I", 0) + tlv(0x1001, struct.pack(">H", len(insts)) + b"".join(insts))))
    fr.append(p45(0x0101, struct.pack(">I", 0) + tlv(0x1001, struct.pack(">H", 1) + insts[0])))
    # PNF RF (0x1002): RF configurations with 1, 2, 4, 8 and an invalid number of antennas
    rfs = b"".join(struct.pack(">HHhhBIIII", i, 7 + i, 20, -10, a, 800000, 900000, 700000, 800000)
                   for i, a in enumerate((1, 2, 4, 8, 3)))
    fr.append(p45(0x0101, struct.pack(">I", 0) + tlv(0x1002, struct.pack(">H", 5) + rfs)))
    return fr


def frames_harq():
    fr = []
    # HARQ TDD PDUs for every mode and several counts, in P7 HARQ.indication instances
    for tag in (0x2027, 0x2028, 0x204F):
        keys = sorted(k for k in HARQ if k[0] == tag)
        n = len(keys)
        body = tlv(0x2026, struct.pack(">H", n) + b"".join(inst(tlv(tag, HARQ[k])) for k in keys))
        fr.append(p7(0x0085, SFN + body, seq=60 + tag % 7))
    return fr


def frames_frag():
    fr = []

    def split(msgid, tl, cuts, seq, base_ts):
        body = SFN + tl
        parts, last = [], 0
        for c in cuts + [len(body)]:
            parts.append(body[last:c])
            last = c
        return [p7(msgid, pt, m=1 if i < len(parts) - 1 else 0, seg=i, seq=seq, ts=base_ts + i)
                for i, pt in enumerate(parts)]

    harq = tlv(0x2026, list_body(3, lambda i: leaf([0x2027, 0x2029, 0x202A][i], i)))
    fr += split(0x0085, harq, [18], 20, 1000)
    fr += split(0x0085, harq, [8, 20], 21, 1100)
    crc = tlv(0x202B, list_body(2, lambda i: leaf(0x202C, i)))
    fr += split(0x0086, crc, [18], 22, 1200)
    dlb = tlv(0x2000, dl_body(0, 1, 2))
    fr += split(0x0080, dlb, [18], 30, 2000)
    fr += split(0x0080, dlb, [9, 30], 31, 2100)
    ulb = tlv(0x200C, ul_body(1, 3))
    fr += split(0x0081, ulb, [16], 32, 2200)
    # a long first fragment: the last fragment's length bounds the TLV walk
    fr += split(0x0083, tlv(0x201D, hi_body(1, 2, 1)), [60], 33, 2300)
    # a missing middle fragment (never completes) and a lone last fragment
    parts = split(0x0085, harq, [8, 20], 23, 1300)
    fr += [parts[0], parts[2]]
    fr += split(0x0080, dlb, [18], 34, 2400)[1:]
    # fragments without payload (offset >= message length)
    fr.append(p7(0x0085, b"", m=1, seg=0, seq=50, length=16))
    fr.append(p7(0x0080, b"", m=1, seg=0, seq=51, length=10))
    # a completed message followed by a repeat of its first fragment
    parts = split(0x0085, crc, [18], 24, 1400)
    fr += parts + [parts[0]]
    return fr


def nest(d):
    b = tlv(0x202D, struct.pack(">H", 0))
    for _ in range(d - 1):
        b = tlv(0x202D, struct.pack(">HH", 1, 2 + len(b)) + b)
    return b


def frames_repro():
    # the bugs fixed on the branch, in the forms that decode cleanly
    fr = []
    # TLV nesting (RX SR body in RX SR body), 5 levels deep
    fr.append(p7(0x008A, SFN + nest(5)))
    # NULL-name configuration tags
    fr.append(p45(0x0100, tlv(0x0006, b"") + tlv(0x0009, b"")))
    fr.append(p7(0x0085, SFN + tlv(0x0006, b"")))
    return fr


def frames_repro_errors():
    # frames that carry an error expert info by design (the last frames of the main capture)
    fr = []
    # nesting past the limit of 8: nfapi.too_deep (an unbounded recursion before the fix)
    fr.append(p7(0x008A, SFN + nest(9)))
    # HARQ TDD with an invalid mode 7 and a count of 0xFFFF (Rel13) / 255 (Rel9): the decoder
    # returns after the expert info; the TLV length then does not match
    fr.append(p7(0x0085, SFN + tlv(0x204F, struct.pack(">BH", 7, 0xFFFF))))
    fr.append(p7(0x0085, SFN + tlv(0x2028, struct.pack(">BB", 7, 255))))
    return fr


def frames_malformed():
    fr = []
    # HARQ TDD with an invalid mode 7 (count 0xFFFF / 255): returns after the expert info,
    # the TLV length then does not match
    fr.append(p7(0x0085, SFN + tlv(0x204F, struct.pack(">BH", 7, 0xFFFF))))
    fr.append(p7(0x0085, SFN + tlv(0x2028, struct.pack(">BB", 7, 255))))
    # nesting at the limit (still fine up to 8) and beyond: nfapi.too_deep
    fr.append(p7(0x008A, SFN + nest(8)))
    fr.append(p7(0x008A, SFN + nest(9)))
    fr.append(p7(0x008A, SFN + nest(40)))
    # the CPU loop forms: thousands of TLVs with an invalid HARQ mode
    fr.append(p7(0x0085, SFN + tlv(0x204F, struct.pack(">BH", 7, 0xFFFF)) * 9000))
    fr.append(p7(0x0085, SFN + tlv(0x2028, struct.pack(">BB", 7, 255)) * 9000))
    # TLV lengths that do not match the decoder
    fr.append(p45(0x0100, tlv(0x1001, b"\x00" * 6)))
    fr.append(p45(0x0100, tlv(0x1000, b"\x00" * 10)))
    # TLV longer than the packet
    fr.append(p45(0x0100, struct.pack(">HH", 0x1000, 500) + b"\x00" * 10))
    fr.append(p45(0x0100, struct.pack(">HH", 0x7000, 500) + b"\x00" * 10))
    # truncated headers and bodies
    fr.append(b"\x00\x00\x01")
    fr.append(b"\x00\x00\x01\x00\x00\x08")
    fr.append(b"\x00\x00\x00\x85\x00\x10\x00")
    fr.append(b"\x00\x00\x01\x00\x00\x09\x00\x00\x10")
    fr.append(p45(0x0103, b"\x00"))
    fr.append(p45(0x0201, b"\x00\x00"))
    fr.append(p45(0x0200, b""))
    fr.append(p45(0x010A, b""))
    fr.append(p45(0x0109, b"\x00"))
    fr.append(p7(0x0180, b"\x00" * 6))
    fr.append(p7(0x0182, b"\x00" * 20))
    fr.append(p7(0x0085, b"\x12"))
    # message length beyond the packet
    fr.append(p7(0x0085, SFN + tlv(0x2026, struct.pack(">H", 0)), length=500))
    fr.append(p7(0x0080, SFN + tlv(0x2000, dl_body(0, 1, 1)), length=0xFFFF))
    # counts past the data in the array bodies
    fr.append(p7(0x0080, SFN + tlv(0x2000, struct.pack(">BBHBH", 2, 200, 100, 1, 0))))
    fr.append(p7(0x0081, SFN + tlv(0x200C, struct.pack(">BBB", 200, 1, 0))))
    fr.append(p7(0x0083, SFN + tlv(0x201D, struct.pack(">HBB", 0, 200, 200))))
    fr.append(p7(0x0084, SFN + tlv(0x2022, struct.pack(">H", 5000))))
    fr.append(p7(0x0084, SFN + tlv(0x2022, struct.pack(">HHH", 1, 5000, 0) + b"\x01\x02")))
    fr.append(p7(0x0085, SFN + tlv(0x2026, struct.pack(">H", 900))))
    fr.append(p7(0x0086, SFN + tlv(0x202B, struct.pack(">H", 900))))
    fr.append(p7(0x0088, SFN + tlv(0x2031, struct.pack(">H", 900))))
    fr.append(p7(0x0089, SFN + tlv(0x2034, struct.pack(">B", 250))))
    fr.append(p7(0x008A, SFN + tlv(0x202D, struct.pack(">H", 900))))
    fr.append(p7(0x008B, SFN + tlv(0x202E, struct.pack(">H", 900))))
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 900))))
    fr.append(p7(0x008C, SFN + tlv(0x2055, struct.pack(">H", 900))))
    fr.append(p7(0x008D, SFN + tlv(0x2058, struct.pack(">H", 900))))
    # CQI body with two instances (the pre-scan walks past each instance) and a cut one
    fr.append(p7(0x008B, SFN + tlv(0x202E, cqi_body(0, [4, 4]))))
    fr.append(p7(0x008B, SFN + tlv(0x202E, cqi_body(0, [4]))[:-3]))
    # RX indication sequences that are not the expected ones
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 2) + leaf(0x2038) +
                                   tlv(0x2024, b"\x00\x04\x00\x00\x09\x00\x07") + b"\x01")))
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 1) +
                                   tlv(0x2024, b"\x00\x04\x00\x00\x09\x00\x07"))))
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 1) + tlv(0x2038, b"\x01") + b"\x99" * 12)))
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 1) + tlv(0x2038, b"\x00" * 6) +
                                   tlv(0x2025, b"\x00\x00") + tlv(0x2024, struct.pack(">HHBH", 7, 0, 9, 7)))))
    fr.append(p7(0x0087, SFN + tlv(0x2023, struct.pack(">H", 1) + leaf(0x2038) +
                                   tlv(0x7000, b"\x00\x00\x00\x00\x00") + b"\x01")))
    # PDU size field smaller than the TLV after it
    fr.append(p7(0x0080, SFN + tlv(0x2000, struct.pack(">BBHBH", 2, 1, 0, 1, 0) + b"\x00\x00")))
    fr.append(p7(0x0081, SFN + tlv(0x200C, struct.pack(">BBB", 1, 0, 0) + b"\x00\x00")))
    # instance lengths of 0 and 1 and past the data
    fr.append(p7(0x0085, SFN + tlv(0x2026, struct.pack(">HH", 1, 0))))
    fr.append(p7(0x0085, SFN + tlv(0x2026, struct.pack(">HH", 1, 1) + b"\x00")))
    fr.append(p7(0x0085, SFN + tlv(0x2026, struct.pack(">HH", 1, 900) + leaf(0x2027))))
    # decoders running off the end of a short TLV
    for t in (0x2001, 0x2006, 0x200D, 0x2024, 0x1000, 0x1001, 0x3000, 0x3002, 0x3014, 0x300B):
        fr.append(p45(0x0100, tlv(t, b"\x01")))
        fr.append(p45(0x0100, tlv(t, b"\x07" * 3)))
    # array counts inside leaf TLVs (lists, antennas, subbands, ...) past the data
    for t in sorted(LEAF):
        if t >= 0x15:
            fr.append(p45(0x0100, tlv(t, b"\xff" * 12)))
    # first fragment shorter than 16 octets: the last fragment's message length runs past the
    # reassembled data (the TLV walk reads beyond it)
    def split2(msgid, tl, c, seq):
        body = SFN + tl
        return [p7(msgid, body[:c], m=1, seg=0, seq=seq), p7(msgid, body[c:], m=0, seg=1, seq=seq)]
    fr += split2(0x0085, tlv(0x2026, list_body(1, lambda i: leaf(0x2027))), 8, 80)
    fr += split2(0x0080, tlv(0x2000, dl_body(0, 1, 0)), 10, 81)
    # fragment oddities
    fr.append(p7(0x0085, SFN + b"\x00" * 3, m=1, seg=0, seq=70))
    fr.append(p7(0x0085, b"\x00\x00\x20\x00", m=0, seg=1, seq=70))
    fr.append(p7(0x0080, SFN + tlv(0x2000, b""), m=1, seg=3, seq=71, length=18))
    return fr


def write_pcap(path, frames):
    with open(path, "wb") as f:
        f.write(struct.pack("<IHHiIII", 0xa1b2c3d4, 2, 4, 0, 0, 262144, 252))
        for i, p in enumerate(frames):
            p = exp() + p
            f.write(struct.pack("<IIII", 1700000000 + i, 0, len(p), len(p)) + p)


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else "."
    verbose = "-v" in sys.argv
    main_frames, sections = [], []
    for name, fn in (("P4/P5 messages", frames_p5), ("TLV tags", frames_tags), ("PNF PHY lists", frames_pnf_phy),
                     ("P7 messages", frames_p7), ("HARQ TDD modes", frames_harq),
                     ("P7 reassembly", frames_frag), ("fixed bugs", frames_repro),
                     ("fixed bugs (errors)", frames_repro_errors)):
        f = fn()
        sections.append((name, len(main_frames) + 1, len(main_frames) + len(f)))
        main_frames += f
    write_pcap(os.path.join(out, "nfapi-coverage.pcap"), main_frames)
    mal = frames_malformed()
    write_pcap(os.path.join(out, "nfapi-coverage-malformed.pcap"), mal)
    if verbose:
        for n, a, b in sections:
            print("%-16s frames %d-%d" % (n, a, b))
        print("main %d frames, malformed capture %d frames" % (len(main_frames), len(mal)))


main()
